const steps = [
  {
    number: '1',
    title: 'Inquiry Process',
    description: 'Drop your queries and our friendly team will guide you through the entire treatment process'
  },
  {
    number: '2',
    title: 'Finding Best Treatment',
    description: 'We suggest the best medical treatment and set up pre-visit counseling with our medical team'
  },
  {
    number: '3',
    title: 'Planning the Visit',
    description: 'We handle ticketing, VISA, and select the most affordable and suitable treatment packages'
  },
  {
    number: '4',
    title: 'Helping with Technicality',
    description: 'Complete assistance with VISA letters and hospital/clinic selection based on your budget'
  },
  {
    number: '5',
    title: 'Airport Assistance',
    description: 'We provide airport assistance, hotel/guest house arrangement, and meal preferences'
  },
  {
    number: '6',
    title: 'Hassle-Free Treatment',
    description: 'Priority consultation and complete care coordination during your treatment period'
  },
  {
    number: '7',
    title: 'Stress-Free Discharge',
    description: 'We stay with you through discharge with all after-care needs and follow-up support'
  },
  {
    number: '8',
    title: 'Handling Follow-up',
    description: 'Continued support even after you return to your country with online doctor consultations'
  },
];

export default function Process() {
  return (
    <section id="process" className="py-20 bg-gray-50">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="text-center mb-16">
          <h2 className="text-4xl font-bold text-gray-900 mb-4">Understanding Our Process</h2>
          <p className="text-xl text-gray-600">A completely transparent journey with full support at every step</p>
        </div>

        <div className="grid md:grid-cols-2 lg:grid-cols-4 gap-8">
          {steps.map((step, index) => (
            <div key={index} className="bg-white p-6 rounded-lg shadow hover:shadow-lg transition">
              <div className="w-12 h-12 bg-blue-600 text-white rounded-full flex items-center justify-center font-bold mb-4">
                {step.number}
              </div>
              <h3 className="text-lg font-semibold text-gray-900 mb-2">{step.title}</h3>
              <p className="text-gray-600 text-sm">{step.description}</p>
            </div>
          ))}
        </div>
      </div>
    </section>
  );
}
